#!/usr/bin/env node
// Codex Splitter: 按模型分流 Codex 的 provider 流量
//   gemini*   -> 本机网关 127.0.0.1:18738 (token 读文件)
//   deepseek* -> DeepSeek 官方 https://api.deepseek.com (key 读文件)
//   其他       -> API 中转 (透传鉴权)
// 请求体可能带压缩编码（zstd/gzip/br），自动解出 model 用于分流；转发时保持原始 body 不变。
import http from 'node:http';
import fs from 'node:fs';
import zlib from 'node:zlib';
import { Readable } from 'node:stream';

const PORT = Number(process.env.PORT || 18739);
const RELAY_BASE = process.env.RELAY_BASE || '__RELAY_BASE__';
const GATEWAY_BASE = process.env.GATEWAY_BASE || '__GATEWAY_BASE__';
const GATEWAY_TOKEN_FILE = process.env.GATEWAY_TOKEN_FILE || `${process.env.HOME}/.config/codex-gemini/gateway-token`;
const DEEPSEEK_BASE = process.env.DEEPSEEK_BASE || 'https://api.deepseek.com';
const DEEPSEEK_KEY_FILE = process.env.DEEPSEEK_KEY_FILE || `${process.env.HOME}/.codex/codex-splitter/deepseek-key`;
const LOG_FILE = process.env.LOG_FILE || `${process.env.HOME}/Library/Logs/codex-splitter.log`;

function log(line) {
  const ts = new Date().toISOString();
  try { fs.appendFileSync(LOG_FILE, `${ts} ${line}\n`); } catch {}
  process.stdout.write(`${ts} ${line}\n`);
}
function gatewayToken() {
  try { return fs.readFileSync(GATEWAY_TOKEN_FILE, 'utf8').trim(); } catch { return null; }
}
function readTrim(file) {
  try { return fs.readFileSync(file, 'utf8').trim(); } catch { return null; }
}

// 尝试从（可能是压缩的）请求体里解出 model
function sniffModel(body, enc) {
  const json = (buf) => { try { const j = JSON.parse(buf.toString('utf8')); return j && typeof j.model === 'string' ? j.model : ''; } catch { return ''; } };
  const regex = (buf) => { const m = /"model"\s*:\s*"([^"]+)"/.exec(buf.toString('utf8')); return m ? m[1] : ''; };
  const magic = body.length >= 4 ? body.subarray(0, 4).toString('hex') : '';
  let model = json(body);
  if (model) return { model, how: 'plain' };
  const tryBuf = (buf, how) => { const m = json(buf) || regex(buf); return m ? { model: m, how, decoded: buf } : null; };
  try {
    if ((enc === 'zstd' || magic.startsWith('28b52ffd')) && typeof zlib.zstdDecompressSync === 'function') {
      const r = tryBuf(zlib.zstdDecompressSync(body), 'zstd'); if (r) return r;
    }
    if (enc === 'gzip' || magic.startsWith('1f8b')) { const r = tryBuf(zlib.gunzipSync(body), 'gzip'); if (r) return r; }
    if (enc === 'deflate') { const r = tryBuf(zlib.inflateSync(body), 'deflate'); if (r) return r; }
    if (enc === 'br') { const r = tryBuf(zlib.brotliDecompressSync(body), 'br'); if (r) return r; }
  } catch (e) { return { model: '', how: `decode-error:${e.message}` }; }
  if (!body.toString('utf8').startsWith('{')) return { model: '', how: `unknown(magic=${magic})` };
  return { model: '', how: 'no-model-field' };
}

const server = http.createServer(async (req, res) => {
  const started = Date.now();
  if (req.method === 'GET' && (req.url === '/healthz' || req.url === '/')) {
    res.writeHead(200, { 'content-type': 'text/plain' }); res.end('ok'); return;
  }
  const chunks = [];
  for await (const c of req) chunks.push(c);
  const body = Buffer.concat(chunks);
  const enc = (req.headers['content-encoding'] || '').toLowerCase();
  const { model, how, decoded } = sniffModel(body, enc);
  const mlc = typeof model === 'string' ? model.toLowerCase() : '';
  const isGemini = mlc.startsWith('gemini');
  const isDeepseek = mlc.startsWith('deepseek');

  const headers = { ...req.headers };
  delete headers.host; delete headers['content-length']; delete headers.connection;
  delete headers['accept-encoding']; // 强制不压缩，代理简单可靠

  let outBody = body;
  let path = req.url;
  let base;
  if (isGemini) {
    base = GATEWAY_BASE;
    if (!path.startsWith('/v1')) path = '/v1' + (path.startsWith('/') ? path : '/' + path);
    const tok = gatewayToken();
    if (tok) headers['authorization'] = `Bearer ${tok}`;
  } else if (isDeepseek) {
    base = DEEPSEEK_BASE;
    const key = readTrim(DEEPSEEK_KEY_FILE);
    if (key) headers['authorization'] = `Bearer ${key}`;
  } else {
    base = RELAY_BASE;
  }
  if ((isGemini || isDeepseek) && decoded) { outBody = decoded; delete headers['content-encoding']; }
  const backend = isGemini ? 'gemini' : isDeepseek ? 'deepseek' : 'relay';

  // 检查是否为 Codex 自动发起的 remote compaction v2 压缩请求
  let jsonObj = null;
  try {
    jsonObj = decoded ? JSON.parse(decoded.toString('utf8')) : JSON.parse(body.toString('utf8'));
  } catch {}

  const isCompaction = Boolean(jsonObj && (
    (Array.isArray(jsonObj.input) && jsonObj.input.length > 0 && jsonObj.input[jsonObj.input.length - 1]?.type === 'compaction_trigger') ||
    jsonObj.client_metadata?.request_kind === 'compaction' ||
    (typeof jsonObj.client_metadata?.['x-codex-turn-metadata'] === 'string' &&
     jsonObj.client_metadata['x-codex-turn-metadata'].includes('"request_kind":"compaction"'))
  ));

  if (isCompaction && (isGemini || isDeepseek)) {
    log(`[COMPACTION INTERCEPT] model=${model} thread=${jsonObj.client_metadata?.thread_id || 'unknown'} -> generating valid compaction item`);
    const cmpId = `cmp_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
    const mockFernet = "gAAAAAB" + Buffer.from(JSON.stringify({
      version: 1,
      created_at: Math.floor(Date.now() / 1000),
      summary: "Context compacted locally by splitter"
    })).toString('base64');
    const respId = `resp_${Date.now()}`;

    res.writeHead(200, {
      'content-type': 'text/event-stream; charset=utf-8',
      'cache-control': 'no-cache',
      'connection': 'keep-alive',
    });

    const itemObj = { type: "compaction", id: cmpId, encrypted_content: mockFernet };
    res.write(`event: response.created\ndata: ${JSON.stringify({ type: "response.created", response: { id: respId, object: "response", status: "in_progress" } })}\n\n`);
    res.write(`event: response.output_item.added\ndata: ${JSON.stringify({ type: "response.output_item.added", output_index: 0, item: itemObj })}\n\n`);
    res.write(`event: response.output_item.done\ndata: ${JSON.stringify({ type: "response.output_item.done", output_index: 0, item: itemObj })}\n\n`);
    res.write(`event: response.completed\ndata: ${JSON.stringify({ type: "response.completed", response: { id: respId, object: "response", status: "completed", output: [itemObj] } })}\n\n`);
    res.end();
    log(`[COMPACTION INTERCEPT COMPLETE] returned valid compaction item to codex (${cmpId}) in ${Date.now() - started}ms`);
    return;
  }

  const target = base + path;
  try {
    const upstream = await fetch(target, { method: req.method, headers, body: outBody.length ? outBody : undefined, redirect: 'manual' });
    const outHeaders = {};
    upstream.headers.forEach((v, k) => {
      const lk = k.toLowerCase();
      if (['content-length', 'transfer-encoding', 'connection', 'content-encoding'].includes(lk)) return;
      outHeaders[k] = v;
    });
    res.writeHead(upstream.status, outHeaders);
    if (upstream.body) Readable.fromWeb(upstream.body).pipe(res); else res.end();
    log(`${backend} ${req.method} ${path} model=${model || '(未识别)'} via=${how} enc=${enc || '-'} fwd=${decoded && outBody !== body ? 'decompressed' : 'as-is'} len=${body.length} -> ${upstream.status} ${Date.now() - started}ms`);
  } catch (e) {
    log(`${backend} ERROR ${req.method} ${path} model=${model || '(未识别)'} via=${how} -> ${e.message}`);
    res.writeHead(502, { 'content-type': 'application/json' });
    res.end(JSON.stringify({ error: { message: `splitter upstream error: ${e.message}`, type: 'splitter_error' } }));
  }
});

server.listen(PORT, '127.0.0.1', () => log(`listening on 127.0.0.1:${PORT} | relay=${RELAY_BASE} gateway=${GATEWAY_BASE} deepseek=${DEEPSEEK_BASE}`));
